CREATE TABLE department (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, name VARCHAR(255) NOT NULL UNIQUE, active BOOLEAN NOT NULL);
CREATE TABLE employee (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_no VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, department_id BIGINT NOT NULL, active BOOLEAN NOT NULL, start_date DATE NOT NULL, end_date DATE, FOREIGN KEY(department_id) REFERENCES department(id));
CREATE TABLE sys_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, username VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL, employee_id BIGINT, enabled BOOLEAN NOT NULL, must_change_password BOOLEAN NOT NULL, FOREIGN KEY(employee_id) REFERENCES employee(id));
CREATE TABLE face_template (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_id BIGINT NOT NULL, encrypted_vector TEXT NOT NULL, model_version VARCHAR(255) NOT NULL, batch VARCHAR(255) NOT NULL, consent BOOLEAN NOT NULL, FOREIGN KEY(employee_id) REFERENCES employee(id));
CREATE TABLE attendance_rule (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, effective_date DATE NOT NULL UNIQUE, start_time TIME NOT NULL, end_time TIME NOT NULL, late_grace_minutes INT NOT NULL, early_grace_minutes INT NOT NULL, in_window_start TIME NOT NULL, in_window_end TIME NOT NULL, out_window_start TIME NOT NULL, out_window_end TIME NOT NULL);
CREATE TABLE work_calendar (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, date DATE NOT NULL UNIQUE, workday BOOLEAN NOT NULL, note VARCHAR(255));
CREATE TABLE punch_device (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, name VARCHAR(255) NOT NULL, token_hash VARCHAR(255) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, revoked BOOLEAN NOT NULL);
CREATE TABLE punch_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, session_id VARCHAR(255) NOT NULL UNIQUE, device_id BIGINT NOT NULL, type VARCHAR(255) NOT NULL, actions VARCHAR(255) NOT NULL, liveness_required BOOLEAN NOT NULL, config_version BIGINT NOT NULL, gallery_version BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL, status VARCHAR(255) NOT NULL, result_message VARCHAR(255), employee_id BIGINT, FOREIGN KEY(device_id) REFERENCES punch_device(id));
CREATE TABLE punch_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_id BIGINT NOT NULL, type VARCHAR(255) NOT NULL, accepted_at TIMESTAMP NOT NULL, source VARCHAR(255) NOT NULL, device_id BIGINT, session_id VARCHAR(255) UNIQUE, liveness_required BOOLEAN NOT NULL, liveness_status VARCHAR(255) NOT NULL, model_version VARCHAR(255), config_version BIGINT NOT NULL, gallery_version BIGINT NOT NULL, FOREIGN KEY(employee_id) REFERENCES employee(id));
CREATE INDEX ix_event_employee_date ON punch_event(employee_id,accepted_at);
CREATE TABLE attendance_daily (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_id BIGINT NOT NULL, date DATE NOT NULL, check_in TIMESTAMP, check_out TIMESTAMP, status VARCHAR(255) NOT NULL, late BOOLEAN NOT NULL, early BOOLEAN NOT NULL, on_leave BOOLEAN NOT NULL, required BOOLEAN NOT NULL, correction_count INT NOT NULL, rule_id BIGINT NOT NULL, rule_snapshot VARCHAR(2000) NOT NULL, UNIQUE(employee_id,date), FOREIGN KEY(employee_id) REFERENCES employee(id), FOREIGN KEY(rule_id) REFERENCES attendance_rule(id));
CREATE TABLE leave_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_id BIGINT NOT NULL, user_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, type VARCHAR(255) NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(255) NOT NULL, reviewer_id BIGINT, comment VARCHAR(255), FOREIGN KEY(employee_id) REFERENCES employee(id), FOREIGN KEY(user_id) REFERENCES sys_user(id));
CREATE INDEX ix_leave_employee ON leave_request(employee_id,start_date,end_date);
CREATE TABLE correction_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, employee_id BIGINT NOT NULL, user_id BIGINT NOT NULL, date DATE NOT NULL, type VARCHAR(255) NOT NULL, requested_time TIME NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(255) NOT NULL, reviewer_id BIGINT, comment VARCHAR(255), pending_key VARCHAR(255) UNIQUE, FOREIGN KEY(employee_id) REFERENCES employee(id), FOREIGN KEY(user_id) REFERENCES sys_user(id));
CREATE TABLE system_setting (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, liveness_enabled BOOLEAN NOT NULL, recognition_threshold DOUBLE NOT NULL, candidate_margin DOUBLE NOT NULL, calibration_confirmed BOOLEAN NOT NULL, config_version BIGINT NOT NULL, gallery_version BIGINT NOT NULL);
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, version BIGINT NOT NULL, actor_id BIGINT, action VARCHAR(255) NOT NULL, target VARCHAR(255) NOT NULL, detail VARCHAR(1000));
